// Load data with different projections
await table.loadGeoData("./data1.geojson"); // Projection: EPSG:4326
await table.loadGeoData("./data2.geojson", { projection: "EPSG:3857" });
// This will throw an error due to differing projections
try {
  await table.union("geomA", "geomB", "unionGeom");
} catch (error) {
  console.error("Error:", error);
}
// We close everything
await sdb.done();
```

