import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable("my_data");
// Check if the SimpleTable instance exists in the database
const existsInstance = await sdb.hasTable(table);
console.log(existsInstance); // Output: true or false
await sdb.done();
```

You can add a timestamp when exporting to Google Sheets:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load your data into the table
await table.loadData("path/to/your/data.csv");
// Export with last update timestamp
await table.toSheet("YOUR_GOOGLE_SHEET_URL", {
  lastUpdate: true
});
// Close everything
await sdb.done();
```

