const tableB = sdb.newTable();
await tableA.loadGeoData("./dataA.geojson");
await tableB.loadGeoData("./dataB.geojson");
// Perform inner join (only matching rows from both tables)
await tableA.joinGeo(tableB, "intersect", {
  type: "inner",
});
await tableA.logTable();
await sdb.done();
```

