  { food: "pizza" },
  { food: "sushi" },
  { food: "burger" },
  { food: "pasta" },
  { food: "salad" },
  { food: "tacos" },
]);
// Generate embeddings for the 'food' column into 'embeddings' column
await table.aiEmbeddings("food", "embeddings", { cache: true });
// Find the 5 most similar foods to 'italian food'
